package com.externalvisuals.modules;
import com.externalvisuals.module.Module; import com.externalvisuals.setting.*; import net.minecraft.particle.ParticleTypes;
public class HitParticles extends Module { public final ModeSetting type=addSetting(new ModeSetting("Type","CRIT","CRIT","ENCHANT","FLAME","HEART")); public final SliderSetting count=addSetting(new SliderSetting("Count",10,1,30,1)); public final SliderSetting spread=addSetting(new SliderSetting("Spread",0.7,0.1,2,0.1)); public final SliderSetting speed=addSetting(new SliderSetting("Speed",0.06,0.01,0.2,0.01)); public HitParticles(){super("Hit Particles");} public void spawn(net.minecraft.entity.Entity e,boolean crit){if(mc.world==null)return; double x=e.getX(),y=e.getY()+e.getHeight()*0.55,z=e.getZ(); for(int i=0;i<count.getValue().intValue();i++){double sx=(mc.world.random.nextDouble()-.5)*spread.getValue(),sy=(mc.world.random.nextDouble()-.5)*spread.getValue(),sz=(mc.world.random.nextDouble()-.5)*spread.getValue(); net.minecraft.particle.ParticleEffect p=type.getValue().equals("ENCHANT")?ParticleTypes.ENCHANT: type.getValue().equals("FLAME")?ParticleTypes.FLAME:type.getValue().equals("HEART")?ParticleTypes.HEART:ParticleTypes.CRIT; mc.particleManager.addParticle(p,x+sx,y+sy,z+sz,sx*speed.getValue(),sy*speed.getValue()+.02,sz*speed.getValue());}} }
